{"content":"1|//! Bounded inventory of explicitly supplied prepared bytes, not deployed state.
2|//!
3|//! Shell dependency analysis preserves quoting, command substitutions and
4|//! backslash continuations without executing them. Supported path-producing
5|//! forms are literals/defaults/aliases, bounded function arguments, lexical
6|//! readlink -f -- $0/dirname/CDPATH+pwd wrappers and mktemp template directories.
7|//! The unix:path= default/prefix-removal pair tracks external socket paths only.
8|//! Other computed executable/config/include paths and unknown path arguments
9|//! remain incomplete. Source-provenance JSON is recognized structurally; mixed
10|//! or unknown schemas keep ordinary configuration scanning.
11|use anyhow::{Context, Result, bail, ensure};
12|use op_cozo_store::{
13|    GraphAssertion, GraphEdge, GraphEvidence, GraphNode, GraphProvenance, GraphProvenanceKind,
14|    GraphSnapshot,
15|};
16|use serde::Deserialize;
17|use serde_json::{Value, json};
18|use sha2::{Digest, Sha256};
19|use std::{
20|    collections::{BTreeMap, BTreeSet},
21|    fs::{self, File, OpenOptions},
22|    io::{Read, Write},
23|    os::unix::{
24|        ffi::OsStrExt,
25|        fs::{MetadataExt, OpenOptionsExt},
26|    },
27|    path::{Component, Path, PathBuf},
28|};
29|
30|const MAX_ENTRIES: usize = 45_000;
31|const MAX_BYTES: u64 = 64 * 1024 * 1024 * 1024;
32|const MAX_TEXT: u64 = 1024 * 1024;
33|const MAX_JSON: usize = 64 * 1024 * 1024;
34|const GRAPH_DIR: &str = "usr/share/op-dbus/graphs";
35|const SERVICE_MANIFEST_DIR: &str = "usr/share/op-dbus/etc/opdbus";
36|const CATALOG_DIR: &str = "usr/share/op-dbus/plugin-blobs";
37|
38|// These are directory ownership boundaries, not another service inventory.
39|const RELEASE_ROOTS: &[(&str, &str, bool)] = &[
40|    ("/usr/share/op-dbus", "usr/share/op-dbus", false),
41|    ("/usr/local/libexec/op-dbus/helpers", "libexec/3tched", false),
42|    ("/usr/local/libexec/op-dbus/bin", "bin", false),
43|    ("/usr/local/libexec/op-dbus/threetched", "usr/bin", false),
44|    ("/usr/local/libexec/op-dbus/sv", "sv", false),
45|    (
46|        "/usr/local/share/op-dbus/dashboard-release",
47|        "usr/local/share/op-dbus/dashboard",
48|        true,
49|    ),
50|    ("/opt/opdbus", "opt/opdbus", false),
51|    ("/opt/op-dbus/execution-python", "opt/op-dbus/execution-python", false),
52|];
53|
54|fn beneath(path: &str, parent: &str) -> bool {
55|    path == parent || path.strip_prefix(parent).is_some_and(|rest| rest.starts_with('/'))
56|}
57|
58|fn valid_service(name: &str) -> bool {
59|    !name.is_empty()
60|        && name.len() <= 128
61|        && !name.starts_with('.')
62|        && !name.ends_with('.')
63|        && name.bytes().all(|c| c.is_ascii_alphanumeric() || b"-_.".contains(&c))
64|}
65|
66|pub fn run(args: Vec<String>) -> Result<()> {
67|    let mut flags = BTreeMap::new();
68|    ensure!(
69|        args.len().is_multiple_of(2),
70|        "usage: system_graph_inventory (--prepared DIR | --source-graph FILE) --output FILE --namespace NAME --generated-at RFC3339"
71|    );
72|    for pair in args.chunks(2) {
73|        ensure!(
74|            [
75|                "--prepared",
76|                "--source-graph",
77|                "--output",
78|                "--namespace",
79|                "--generated-at"
80|            ]
81|            .contains(&pair[0].as_str()),
82|            "unknown option {}",
83|            pair[0]
84|        );
85|        ensure!(
86|            flags.insert(pair[0].clone(), pair[1].clone()).is_none(),
87|            "duplicate option {}",
88|            pair[0]
89|        );
90|    }
91|    let required = |key: &str| flags.get(key).context(format!("required option {key}"));
92|    let namespace = required("--namespace")?;
93|    let generated_at = required("--generated-at")?;
94|    chrono::DateTime::parse_from_rfc3339(generated_at).context("invalid --generated-at")?;
95|    let output = PathBuf::from(required("--output")?);
96|    let mut snapshot = match (flags.get("--prepared"), flags.get("--source-graph")) {
97|        (Some(root), None) => {
98|            ensure!(
99|                namespace.starts_with("release:"),
100|                "prepared namespace must start with release:"
101|            );
102|            prepared(Path::new(root), namespace, generated_at, &output)?
103|        }
104|        (None, Some(input)) => {
105|            ensure!(
106|                namespace.starts_with("source:"),
107|                "source namespace must start with source:"
108|            );
109|            source_graph(Path::new(input), namespace, generated_at)?
110|        }
111|        _ => bail!("supply exactly one of --prepared or --source-graph"),
112|    };
113|    snapshot.edges = merge_edges(snapshot.edges)?;
114|    op_cozo_store::system_graph_snapshot_digest(&snapshot)?;
115|    atomic_write(&output, &serde_json::to_vec_pretty(&snapshot)?)?;
116|    println!(
117|        "{}: {} nodes, {} edges; prepared source only",
118|        namespace,
119|        snapshot.nodes.len(),
120|        snapshot.edges.len()
121|    );
122|    Ok(())
123|}
