207|struct Builder {
208|    nodes: BTreeMap<String, GraphNode>,
209|    edges: Vec<GraphEdge>,
210|    paths: BTreeSet<String>,
211|    bytes: u64,
212|    release_roots: BTreeMap<String, String>,
213|    blockers: BTreeMap<String, BTreeSet<String>>,
214|    argument_paths: BTreeMap<String, BTreeMap<String, BTreeSet<String>>>,
215|    template_roots: BTreeMap<String, BTreeSet<String>>,
216|    conservative: BTreeSet<String>,
217|}
218|impl Builder {
219|    fn new() -> Self {
220|        Self {
221|            nodes: BTreeMap::new(),
222|            edges: Vec::new(),
223|            paths: BTreeSet::new(),
224|            bytes: 0,
225|            release_roots: BTreeMap::new(),
226|            blockers: BTreeMap::new(),
227|            argument_paths: BTreeMap::new(),
228|            template_roots: BTreeMap::new(),
229|            conservative: BTreeSet::new(),
230|        }
231|    }
232|    fn node(&mut self, id: String, kind: &str, label: String, attributes: Value) -> Result<()> {
233|        ensure!(
234|            self.nodes.len() < MAX_ENTRIES,
235|            "prepared graph entry bound exceeded"
236|        );
237|        self.nodes.insert(
238|            id.clone(),
239|            GraphNode {
240|                id,
241|                kind: kind.into(),
242|                label,
243|                attributes: attrs(attributes),
244|            },
245|        );
246|        Ok(())
247|    }
248|    fn walk(&mut self, root: &Path, relative: &Path, depth: usize) -> Result<()> {
249|        ensure!(depth <= 64, "prepared directory depth bound exceeded");
250|        let dir = root.join(relative);
251|        ensure!(
252|            fs::symlink_metadata(&dir)?.is_dir(),
253|            "prepared directory replaced during inventory"
254|        );
255|        let mut entries = Vec::new();
256|        for entry in fs::read_dir(&dir)? {
257|            ensure!(
258|                entries.len() + self.nodes.len() < MAX_ENTRIES,
259|                "prepared directory entry bound exceeded"
260|            );
261|            entries.push(entry?);
262|        }
263|        entries.sort_by_key(|e| e.file_name());
264|        for entry in entries {
265|            let rel = relative.join(entry.file_name());
266|            let name = safe_rel(&rel)?;
267|            if name == GRAPH_DIR || name.starts_with(&format!("{GRAPH_DIR}/")) {
268|                continue;
269|            }
270|            let path = root.join(&rel);
271|            let metadata = fs::symlink_metadata(&path)?;
272|            let id = format!("file:{name}");
273|            let file_type = if metadata.is_dir() {
274|                "directory"
275|            } else if metadata.is_file() {
276|                "regular"
277|            } else if metadata.file_type().is_symlink() {
278|                "symlink"
279|            } else {
280|                bail!("special file not permitted in prepared tree: {name}")
281|            };
282|            let mut properties = attrs(
283|                json!({"path":name,"file_type":file_type,"size":metadata.len(),"mode":metadata.mode() & 0o7777,"uid":metadata.uid(),"gid":metadata.gid(),"category":category(&name),"authority":"prepared_release","release_target":null,"consumers":[]}),
284|            );
285|            if name == "MANIFEST" {
286|                properties.remove("size");
287|            }
288|            if metadata.is_file() && name != "MANIFEST" && !sensitive(&name) {
289|                self.bytes = self
290|                    .bytes
291|                    .checked_add(metadata.len())
292|                    .context("byte count overflow")?;
293|                ensure!(
294|                    self.bytes <= MAX_BYTES,
295|                    "prepared input byte bound exceeded"
296|                );
297|                properties.insert("sha256".into(), json!(hash_file(&path, &metadata)?));
298|            } else if metadata.is_file() {
299|                properties.insert(
300|                    "hash_status".into(),
301|                    json!(if name == "MANIFEST" {
302|                        "excluded_to_avoid_graph_digest_recursion"
303|                    } else {
304|                        "protected_content_not_read"
305|                    }),
306|                );
307|            }
308|            if metadata.file_type().is_symlink() {
309|                let target = fs::read_link(&path)?;
310|                ensure!(
311|                    target.as_os_str().as_bytes().len() <= 4096,
312|                    "symlink target exceeds bound"
313|                );
314|                // Read only the literal destination; later graph resolution is lexical, never a filesystem follow.
315|                let raw = target.to_str().context("non-UTF8 symlink target")?;
316|                properties.insert("target".into(), json!(raw));
317|                properties.insert("target_status".into(), json!("not_followed"));
318|            }
319|            self.paths.insert(name.clone());
320|            self.node(
321|                id.clone(),
322|                "prepared_path",
323|                name.clone(),
324|                Value::Object(properties.into_iter().collect()),
325|            )?;
326|            if relative != Path::new("") {
327|                self.edges.push(edge(
328|                    format!("file:{}", safe_rel(relative)?),
329|                    "contains",
330|                    id.clone(),
331|                    &name,
332|                    "directory_entry",
333|                    json!({}),
334|                ));
335|            }
336|            if metadata.is_dir() {
337|                self.walk(root, &rel, depth + 1)?;
338|            }
339|        }
340|        Ok(())
341|    }
