473|fn hash_file(path: &Path, before: &fs::Metadata) -> Result<String> {
474|    let mut file = OpenOptions::new()
475|        .read(true)
476|        .custom_flags(nix::libc::O_NOFOLLOW)
477|        .open(path)?;
478|    let opened = file.metadata()?;
479|    ensure!(
480|        before.dev() == opened.dev()
481|            && before.ino() == opened.ino()
482|            && before.len() == opened.len(),
483|        "prepared file changed before read"
484|    );
485|    let mut hasher = Sha256::new();
486|    let mut buf = [0u8; 65536];
487|    let mut total = 0u64;
488|    loop {
489|        let len = file.read(&mut buf)?;
490|        if len == 0 {
491|            break;
492|        }
493|        total += len as u64;
494|        ensure!(total <= before.len(), "prepared file grew while hashing");
495|        hasher.update(&buf[..len]);
496|    }
497|    let after = file.metadata()?;
498|    ensure!(
499|        total == before.len()
500|            && before.mtime() == after.mtime()
501|            && before.mtime_nsec() == after.mtime_nsec()
502|            && before.ctime() == after.ctime()
503|            && before.ctime_nsec() == after.ctime_nsec(),
504|        "prepared file changed while hashing"
505|    );
506|    Ok(format!("{:x}", hasher.finalize()))
