1442|    let mut service_properties = Vec::new();
1443|    let mut blockers = BTreeSet::new();
1444|    for service in b.nodes.values().filter(|node| {
1445|        node.kind == "runit_service" && node.attributes.get("release_owned") == Some(&json!(true))
1446|    }) {
1447|        let mut seen = BTreeSet::new();
1448|        let mut pending = vec![service.id.as_str()];
1449|        let mut deps = BTreeSet::new();
1450|        let mut starts = BTreeSet::new();
1451|        while let Some(id) = pending.pop() {
1452|            if !seen.insert(id) {
