1470|            for edge in adjacency.get(id).into_iter().flatten() {
1471|                match edge.relation.as_str() {
1472|                    "depends_on" | "starts" => {
1473|                        let name = edge.dst.strip_prefix("service:").context("invalid service reference")?;
1474|                        if name != service.label {
