112|    esac
113|    case "$container" in
114|        "$session") ;;
115|        "$session"-archived-????????)
116|            printf '%s' "$container" | grep -Eq "^${session}-archived-[0-9]{8}$" || {
117|                log "$container: invalid archived identity name"
118|                return 1
119|            }
120|            ;;
121|        *) log "$container: name does not match its identity session"; return 1 ;;
122|    esac
123|    public_key=$(incus config get "$container" user.opdbus.wireguard_public_key 2>/dev/null) || {
124|        log "$container: no identity key binding"
125|        return 1
126|    }
127|    [ -n "$public_key" ] || {
128|        log "$container: empty identity key binding"
129|        return 1
130|    }
