1133|fn function_arguments(
1134|    b: &mut Builder,
1135|    source: &str,
1136|    lines: &[(usize, std::borrow::Cow<'_, str>)],
1137|) -> Result<BTreeMap<String, BTreeMap<String, BTreeSet<String>>>> {
1138|    let mut functions = BTreeMap::new();
1139|    let mut incomplete = BTreeMap::<String, (usize, BTreeSet<usize>)>::new();
1140|    let mut quoted = false;
1141|    for (_, raw) in lines {
1142|        if let Some(name) = shell_function(shell_code(raw, &mut quoted).trim()) {
1143|            if name != "wait_dep" {
1144|                functions.insert(name.to_owned(), BTreeMap::new());
1145|            }
1146|        }
1147|    }
1148|    quoted = false;
1149|    let mut bindings = b.argument_paths.get(source).cloned().unwrap_or_default();
1150|    if let Some(host) = b.host_path(source) {
1151|        bindings.insert("0".into(), BTreeSet::from([host]));
1152|    }
1153|    let mut outer = None;
1154|    for (_, raw) in lines {
1155|        let line = shell_code(raw, &mut quoted).trim();
1156|        if shell_function(line).is_some() {
1157|            outer = Some(bindings.clone());
1158|            bindings.retain(|name, _| !name.bytes().all(|c| c.is_ascii_digit()));
1159|        } else if line == "}" {
1160|            if let Some(saved) = outer.take() {
1161|                bindings = saved;
1162|            }
1163|        }
1164|        if line.starts_with('#') || shell_function(line).is_some() {
1165|            continue;
1166|        }
1167|        for words in shell_commands(line)? {
1168|            bind_shell_command(&words, &mut bindings);
1169|            if matches!(words.first(), Some(&".") | Some(&"source")) {
1170|                bindings.retain(|_, paths| !paths.iter().any(|path| {
1171|                    b.release_roots.keys().any(|root| beneath(path, root))
1172|                }));
1173|            }
1174|            let Some(position) = executable_position(&words) else { continue };
1175|            let Some(arguments) = functions.get_mut(shell_word(words[position])) else { continue };
1176|            let (minimum_arity, unbounded) = incomplete
1177|                .entry(shell_word(words[position]).to_owned())
1178|                .or_insert_with(|| (usize::MAX, BTreeSet::new()));
1179|            *minimum_arity = (*minimum_arity).min(words.len() - position - 1);
1180|            for (index_arg, word) in words[position + 1..].iter().enumerate() {
1181|                let paths = declared_paths(word, &bindings);
1182|                if paths.is_empty() {
1183|                    unbounded.insert(index_arg + 1);
1184|                }
1185|                arguments.entry((index_arg + 1).to_string()).or_insert_with(BTreeSet::new).extend(paths);
1186|            }
1187|        }
1188|    }
1189|    for (name, arguments) in &functions {
1190|        if let Some((minimum_arity, unbounded)) = incomplete.get(name) {
1191|            for (position, paths) in arguments {
1192|                let position = position.parse::<usize>().expect("positional binding");
1193|                if !paths.is_empty() && (position > *minimum_arity || unbounded.contains(&position)) {
1194|                    b.blocker(source, 0, "function path argument is not bounded at every invocation");
1195|                }
1196|            }
1197|        }
1198|    }
1199|    Ok(functions)
