1218|    let functions = if shell { function_arguments(b, source, &lines)? } else { BTreeMap::new() };
1219|    let mut outer_bindings = None;
1220|    let mut wait_function = false;
1221|    let mut wait_starts = false;
1222|    let mut wait_alias = "1";
