600|// Keep shell words intact: quoted whitespace and nested substitutions are not
601|// argument boundaries. Substitutions are scanned for dependencies, never run.
602|// This is a bounded dependency lexer, not a shell interpreter or syntax checker.
603|fn shell_commands(line: &str) -> Result<Vec<Vec<&str>>> {
604|    fn group_end(bytes: &[u8], mut i: usize, close: u8, depth: usize) -> Result<usize> {
605|        ensure!(depth <= 32, "shell substitution nesting exceeds inventory bound");
606|        let mut quote = 0;
607|        while i < bytes.len() {
608|            let ch = bytes[i];
609|            if ch == b'\\' && quote != b'\'' {
610|                i += 2;
611|                continue;
612|            }
613|            if ch == quote {
614|                quote = 0;
615|            } else if quote != b'\'' && ch == b'$' && matches!(bytes.get(i + 1), Some(b'(' | b'{')) {
616|                let end = if bytes[i + 1] == b'(' { b')' } else { b'}' };
617|                i = group_end(bytes, i + 2, end, depth + 1)?;
618|            } else if quote == 0 {
619|                if ch == close {
620|                    return Ok(i);
621|                }
622|                if matches!(ch, b'\'' | b'"') {
623|                    quote = ch;
624|                } else if ch == b'(' {
625|                    i = group_end(bytes, i + 1, b')', depth + 1)?;
626|                }
627|            }
628|            i += 1;
629|        }
630|        // A command may continue on the following physical line (e.g. a pipe
631|        // inside $()). Keep its operands, but never invent its output.
632|        Ok(bytes.len())
633|    }
634|    fn lex<'a>(line: &'a str, depth: usize, commands: &mut Vec<Vec<&'a str>>) -> Result<()> {
635|        ensure!(depth <= 32, "shell substitution nesting exceeds inventory bound");
636|        let bytes = line.as_bytes();
637|        let mut words = Vec::new();
638|        let mut start = None;
639|        let mut quote = 0;
640|        let mut i = 0;
641|        while i < bytes.len() {
642|            let ch = bytes[i];
643|            if ch == b'\\' && quote != b'\'' {
644|                start.get_or_insert(i);
645|                i += 2;
646|                continue;
647|            }
648|            if ch == quote {
649|                quote = 0;
650|            } else if quote != b'\'' && ch == b'$' && matches!(bytes.get(i + 1), Some(b'(' | b'{')) {
651|                start.get_or_insert(i);
652|                let close = if bytes[i + 1] == b'(' { b')' } else { b'}' };
653|                let end = group_end(bytes, i + 2, close, depth + 1)?;
654|                if close == b')' && bytes.get(i + 2) != Some(&b'(') {
655|                    lex(&line[i + 2..end], depth + 1, commands)?;
656|                }
657|                i = end;
658|            } else if quote == 0 {
659|                if matches!(ch, b'\'' | b'"') {
660|                    quote = ch;
661|                } else if ch.is_ascii_whitespace() || b";|&()".contains(&ch) {
662|                    if let Some(begin) = start.take() {
663|                        words.push(&line[begin..i]);
664|                    }
665|                    if !ch.is_ascii_whitespace() && !words.is_empty() {
666|                        commands.push(std::mem::take(&mut words));
667|                    }
668|                    i += 1;
669|                    continue;
670|                }
671|            }
672|            start.get_or_insert(i.min(bytes.len()));
673|            i += 1;
674|        }
675|        if let Some(begin) = start {
676|            if begin < bytes.len() {
677|                words.push(&line[begin..]);
678|            }
679|        }
680|        if !words.is_empty() {
681|            commands.push(words);
682|        }
683|        Ok(())
684|    }
685|    let mut commands = Vec::new();
686|    lex(line, 0, &mut commands)?;
687|    Ok(commands)
