803|        if let Some(arg) = command.strip_prefix("readlink -f -- ").filter(|arg| shell_word(arg) == "$0") {
804|            return declared_paths(arg, bindings);
805|        }
806|        if let Some(arg) = command.strip_prefix("CDPATH= cd -- ").and_then(|word| word.strip_suffix(" && pwd -P")) {
807|            return declared_paths(arg, bindings);
808|        }
