810|            let Ok(commands) = shell_commands(command) else { return result };
811|            let Some(words) = commands.first().filter(|_| commands.len() == 1) else { return result };
812|            let template = match words.as_slice() {
813|                ["mktemp", template] | ["mktemp", "-d", template] => *template,
814|                _ => return result,
815|            };
816|            return declared_paths(template, bindings).into_iter().filter_map(|path| {
817|                Path::new(&path).parent().and_then(Path::to_str).map(String::from)
818|            }).collect();
819|        }
820|        return result;
821|    }
822|    if word.starts_with('/') {
823|        if word.contains([';', '|', '&', '(', ')', '"', '\'', '\\']) {
